flow.set('ai_busy', true);
const prompt = msg.prompt || (typeof msg.payload === 'string' ? msg.payload : JSON.stringify(msg.payload));
let cmd = `agy -p ${JSON.stringify(prompt)} --dangerously-skip-permissions`;
if (msg.schema) {
    const schemaStr = typeof msg.schema === 'object' ? JSON.stringify(msg.schema) : msg.schema;
    cmd += ` --json-schema ${JSON.stringify(schemaStr)} --output-format json`;
}
msg.payload = cmd;
return msg;

let parsed;
try {
    parsed = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload;
} catch (e) {
    parsed = { response: msg.payload };
}
let result = parsed.structured_output;
if (!result && parsed.response) {
    try {
        result = typeof parsed.response === 'string' ? JSON.parse(parsed.response) : parsed.response;
    } catch (e) {
        result = parsed.response;
    }
}
if (typeof result === 'string') {
    try {
        result = JSON.parse(result);
    } catch (e) {
        node.error(`AI 輸出非 JSON 格式 (觸發退避自癒): ${result}`, msg);
        return null;
    }
}
msg.payload = result || parsed;
return msg;

const total = os.totalmem();
const free = os.freemem();
const homedir = os.homedir();
const downloadDir = path.join(homedir, 'Downloads');
let files = [];
let sourceError = null;
try {
  if (fs.existsSync(downloadDir)) files = fs.readdirSync(downloadDir).filter(name => !name.startsWith('.') && !name.endsWith('.crdownload')).map(name => { const p = path.join(downloadDir, name); const s = fs.statSync(p); return s.isFile() ? { filename: name, path: p, size_bytes: s.size, modified_at: s.mtime.toISOString(), stable: true } : null; }).filter(Boolean).slice(0, 5);
} catch (err) { sourceError = err.message; }
msg.payload = { task_id: `task_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`, task_type: 'CLASSIFY_FILE', source: 'DAY24_INGESTION', input: { collected_at: new Date().toISOString(), download_dir: downloadDir, metrics: { mem_percent: Math.round(((total - free) / total) * 100), is_heavy: Math.round(((total - free) / total) * 100) > 80 }, files, source_error: sourceError } };
return msg;

const data = msg.payload || {};
if (!data.task_id || !data.input) { node.error('缺少 Task Envelope'); return null; }
msg.task = data;
msg.payload = data;
return msg;

const task = msg.task || msg.payload;
const key = crypto.createHash('md5').update(JSON.stringify({ task_type: task.task_type, input: task.input, prompt_version: 'v1' })).digest('hex');
const cache = flow.get('e2e_cache') || {};
if (cache[key] && Date.now() - cache[key].timestamp < 3600000) {
    msg.payload = cache[key].data;
    msg.decision = cache[key].data;
    msg.fromCache = true;
    return [msg, null];
}
if (flow.get('ai_busy')) {
    msg.payload = { status: 'THROTTLED', task_id: task.task_id, reason: 'AI 名額已滿' };
    return [null, msg];
}
flow.set('ai_busy', true);
msg.cacheKey = key;
msg.retryCount = msg.retryCount || 0;
const file = task.input.files && task.input.files[0];
msg.prompt = `請將檔案「${file ? file.filename : ''}」分類到 Installers、Documents、Archives、Media 或 Others，並回傳 category、reason、filename。`;
msg.schema = { type: 'object', properties: { filename: {type:'string'}, category: {type:'string', enum:['Installers','Documents','Archives','Media','Others']}, reason: {type:'string'} }, required:['filename','category','reason'] };
return [null, msg];

flow.set('ai_busy', false);
const result = msg.payload;
msg.decision = result;
if (msg.cacheKey) {
    const cache = flow.get('e2e_cache') || {};
    cache[msg.cacheKey] = { data: result, timestamp: Date.now() };
    flow.set('e2e_cache', cache);
}
return msg;

let data;
try { data = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload; } catch (err) { data = {}; }
if (!data || typeof data !== 'object') data = {};
const task = msg.task || {}; const input = task.input || {};
const allowed = ['Installers','Documents','Archives','Media','Others']; const category = allowed.includes(data.category) ? data.category : null;
const base = path.resolve(input.download_dir || path.join(os.homedir(), 'Downloads')); const filename = path.basename(data.filename || input.files?.[0]?.filename || '');
const source = path.resolve(path.join(base, filename)); const target = category ? path.resolve(path.join(base, category, filename)) : null;
let status = 'REJECTED'; let error = category ? null : '分類不在白名單或非結構化結果';
if (category && (!filename || !source.startsWith(base + path.sep) || !target.startsWith(base + path.sep))) error = '缺少檔名或路徑越界';
else if (category && (!fs.existsSync(source) || !fs.statSync(source).isFile())) { status = 'SKIPPED'; error = '來源檔案不存在'; }
else if (category) { try { fs.mkdirSync(path.dirname(target), {recursive:true}); if (source !== target) fs.renameSync(source, target); status = 'SUCCESS'; } catch (err) { status = 'FAILED'; error = err.message; } }
const auditDir = path.join(os.homedir(), 'SystemLogs'); fs.mkdirSync(auditDir, {recursive:true});
const audit = { task_id: task.task_id || null, timestamp: new Date().toISOString(), action:'MOVE_FILE', status, source, target, category, error }; fs.appendFileSync(path.join(auditDir, 'audit_trail.log'), JSON.stringify(audit) + '\n', 'utf8');
msg.payload = audit; return msg;

msg.retryCount = (msg.retryCount || 0) + 1;
flow.set('ai_busy', false);
if (msg.retryCount <= 3) {
    const delay = Math.pow(2, msg.retryCount - 1) * 1000;
    msg.delay = delay;
    msg.retry_delay_ms = delay;
    node.warn(`⏳ 第 ${msg.retryCount} 次重試，實際等待 ${delay}ms...`);
    return [msg, null];
}
msg.payload = { status: 'FALLBACK_LOCAL', action: 'SKIP_FILE_OPERATION', reason: 'AI CLI 重試耗盡' };
return [null, msg];
